function accountsPanel(){const ordered=state.accounts.map(a=>({a,balance:accountBalance(state,a.id,dateAt(month,31))})).filter(x=>x.balance!==0).sort((x,y)=>y.balance-x.balance).slice(0,5);return `<section class="panel"><div class="panelhead"><h2>Onde está seu dinheiro</h2>${button('Ver contas','nav','right','subtle small','accounts')}</div><div class="panelbody">${ordered.length?ordered.map(({a,balance})=>`<div class="account-row"><div class="account-symbol" style="color:${a.color};background:${a.color}15">${esc(a.name.slice(0,2))}</div><div class="row-detail"><strong>${esc(a.name)}</strong><small>${kindName[a.kind]}</small></div><div class="row-money">${money(balance)}</div></div>`).join(''):empty('Cada conta tem seu lugar','Cadastre contas, dinheiro em espécie e reservas.','new-account','Adicionar conta','accounts')}</div></section>`}
function recentPanel(){const ts=state.transactions.filter(t=>t.date.slice(0,7)===month).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return `<section class="panel"><div class="panelhead"><h2>Últimos lançamentos</h2>${button('Ver todos','nav','right','subtle small','transactions')}</div>${ts.length?txTable(ts,false):empty('Um novo começo','Seus lançamentos deste mês aparecerão aqui.','new-tx','Registrar lançamento')}</section>`}
function recurringPayments(r){return state.transactions.filter(t=>t.recurringId===r.id&&t.recurringMonth===month)}
function recurringPaid(r){return recurringPayments(r)[0]}
function recurringFlexible(r){return r.schedule==='flexible'}
function recurringOccurrences(r){return recurringFlexible(r)?Math.max(1,Number(r.occurrences)||1):1}
function recurringExpected(r){return r.amount*recurringOccurrences(r)}
function recurringPending(r){return recurringFlexible(r)?recurringPayments(r).length<recurringOccurrences(r):!recurringPaid(r)}
function recurringDetail(r){if(recurringFlexible(r)){const done=recurringPayments(r).length,left=Math.max(0,recurringOccurrences(r)-done);return `${done}/${recurringOccurrences(r)} no mês · ${left?`faltam ${left}`:'concluído'}`}const d=dateAt(month,r.day);return d<today()?'Vencimento passado':'Vence em '+shortDate(d)}
function fixedPanel(){const rs=state.recurring.filter(recurringPending).sort((a,b)=>(a.schedule==='flexible'?99:a.day)-(b.schedule==='flexible'?99:b.day)).slice(0,4);return `<section class="panel"><div class="panelhead"><h2>Compromissos do mês</h2>${button('Ver todos','nav','right','subtle small','fixed')}</div><div class="panelbody">${rs.length?rs.map(r=>`<div class="due-row"><div class="account-symbol">${r.schedule==='flexible'?'↻':r.day}</div><div class="row-detail"><strong>${esc(r.name)}</strong><small>${esc(recurringDetail(r))}</small></div><div class="row-money">${money(r.amount)}${recurringFlexible(r)?'<small>por vez</small>':''}</div>${button('Registrar','pay-fixed','','small',r.id)}</div>`).join(''):empty(state.recurring.length?'Tudo em dia neste mês':'Seu mês, mais previsível',state.recurring.length?'Os gastos fixos cadastrados já foram pagos.':'Cadastre seus compromissos recorrentes.','new-fixed','Adicionar gasto fixo','fixed')}</div></section>`}
function txTable(ts,full=true){const custom=full?state.settings.fields:[];return `<div class="tablewrap"><table class="${state.settings.density==='compact'?'compact':''}"><thead><tr><th>Descrição</th><th>Data</th>${full?'<th>Conta</th>':''}<th style="text-align:right">Valor</th>${custom.map(f=>`<th>${esc(f.name)}</th>`).join('')}${full?'<th>Ações</th>':''}</tr></thead><tbody>${ts.map(t=>`<tr><td class="desc"><div class="txdesc"><span class="txicon ${t.type==='income'?'positive':''}">${icon(t.type==='income'?'down':t.type==='transfer'?'transactions':'up')}</span><div>${esc(t.description)}<small>${t.type==='transfer'?'Transferência':esc(categoryName(t.categoryId))}</small>${t.notes?`<small class="tx-note">${esc(t.notes)}</small>`:''}</div></div></td><td class="muted">${shortDate(t.date)}</td>${full?`<td>${esc(accountName(t.accountId))}${t.type==='transfer'?` <span class="muted">→ ${t.toInvestmentId?'Investimentos · '+esc(investmentName(t.toInvestmentId)):esc(accountName(t.toAccountId))}</span>`:''}</td>`:''}<td class="money ${t.type==='income'?'positive':t.type==='expense'?'negative':''}">${t.type==='income'?'+ ':t.type==='expense'?'− ':''}${money(t.amount)}</td>${custom.map(f=>`<td>${esc(t.extra?.[f.id]||'—')}</td>`).join('')}${full?`<td><div class="actions"><button class="subtle small" data-action="edit-tx" data-id="${t.id}" title="Editar lançamento" aria-label="Editar ${esc(t.description)}">${icon('edit')}</button><button class="subtle small danger" data-action="delete-tx" data-id="${t.id}" title="Excluir lançamento" aria-label="Excluir ${esc(t.description)}">${icon('trash')}</button></div></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function filteredTx(){return state.transactions.filter(t=>(txRange==='all'||t.date.slice(0,7)===month)&&(filter==='all'||t.type===filter)&&(accountFilter==='all'||t.accountId===accountFilter||t.toAccountId===accountFilter)&&(categoryFilter==='all'||t.categoryId===categoryFilter)&&`${t.description} ${t.notes||''} ${categoryName(t.categoryId)}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date))}
function refreshTxTable(){document.querySelector('#tx-results').innerHTML=txResults()}
function txResults(){const ts=filteredTx(),net=ts.reduce((n,t)=>n+(t.type==='expense'?-t.amount:t.type==='income'?t.amount:0),0);return `<div class="tx-filter-summary"><div><span>Lançamentos filtrados</span><strong>${ts.length}</strong></div><div><span>Saldo do filtro</span><strong class="${net>=0?'positive':'negative'}">${net>=0?'+ ': '− '}${money(Math.abs(net))}</strong></div></div>${ts.length?txTable(ts):empty('Nenhum lançamento encontrado',txRange==='all'?'Ajuste os filtros ou registre uma movimentação.':'Escolha outro mês, ajuste os filtros ou registre uma movimentação.','new-tx','Novo lançamento')}`}
function transactionsPage(){const categoryType=filter==='income'?'income':filter==='expense'?'expense':'',categoryOptions=[['all','Todas as categorias'],...state.categories.filter(c=>!categoryType||c.type==='both'||c.type===categoryType).map(c=>[c.id,c.name])],ts=filteredTx(),income=ts.filter(t=>t.type==='income').reduce((n,t)=>n+t.amount,0),periodLabel=txRange==='all'?'Todos os períodos':monthName(month);return `<div class="filters transactions-filters"><select id="tx-period" aria-label="Período"><option value="month" ${txRange==='month'?'selected':''}>Apenas este mês</option><option value="all" ${txRange==='all'?'selected':''}>Todos os períodos</option></select><input id="tx-search" aria-label="Buscar lançamentos" placeholder="Buscar descrição, categoria ou observação…" value="${esc(search)}"><select id="tx-filter" aria-label="Tipo de lançamento">${[['all','Todos os tipos'],['income','Receitas'],['expense','Despesas'],['transfer','Transferências']].map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select><select id="category-filter" aria-label="Filtrar categoria">${categoryOptions.map(([v,l])=>`<option value="${esc(v)}" ${categoryFilter===v?'selected':''}>${esc(l)}</option>`).join('')}</select><select id="account-filter" aria-label="Filtrar conta"><option value="all">Todas as contas</option>${acOpts().map(([id,n])=>`<option value="${id}" ${id===accountFilter?'selected':''}>${esc(n)}</option>`).join('')}</select></div><section class="panel"><div class="panelhead"><h2>Movimentações · ${periodLabel}</h2><span class="meta muted">Entradas ${money(income)}</span></div><div id="tx-results">${txResults()}</div></section><p class="hint">Busque pelo nome, categoria ou observação. Em “Todos os períodos”, a lista reúne o histórico completo.</p>`}
function accountsPage(){return state.accounts.length?`<div class="three">${state.accounts.map(a=>`<section class="card"><div class="card-top"><div class="account-symbol" style="color:${a.color};background:${a.color}15">${esc(a.name.slice(0,2))}</div><div class="actions">${button('Editar','edit-account','edit','subtle small',a.id)}${button('','delete-account','trash','subtle small danger',a.id)}</div></div><h2>${esc(a.name)}</h2><p class="meta muted">${kindName[a.kind]}</p><div class="card-amount">${money(accountBalance(state,a.id,today()))}</div><div class="meta muted">Saldo até hoje</div><div class="splitline"><span class="muted">Data inicial</span><span>${shortDate(a.openingDate)}</span></div>${button('Movimentar','account-tx','plus','small full',a.id)}</section>`).join('')}</div><p class="hint">Contas correntes e espécie compõem o saldo disponível. Reservas e garantias compõem o guardado. O saldo inicial deve ser anterior aos lançamentos que você cadastrar.</p>`:`<section class="panel">${empty('Comece pelo lugar onde seu dinheiro está','Crie contas com nome, cor e saldo inicial. Você pode mudar tudo isso depois.','new-account','Criar primeira conta','accounts')}</section>`}
function cardsPage(){return state.cards.length?`<div class="two">${state.cards.map(c=>{const inv=invoice(state,c.id,month),debt=outstanding(state,c.id),limit=Math.max(0,c.limit-debt);return `<section class="panel"><div class="panelbody" style="padding-top:22px"><div class="credit-visual" style="background:${c.color}"><div class="actions"><h2>${esc(c.name)}</h2>${icon('cards')}</div><div><div class="meta">Limite disponível</div><div class="card-amount">${money(limit)}</div></div><div class="actions meta"><span>Fecha dia ${c.closing}</span><span>Vence dia ${c.due}</span></div></div><div class="splitline sectiongap"><span>Fatura · ${monthName(month)}</span><strong>${money(inv.total)}</strong></div><div class="progress"><div style="width:${Math.min(100,c.limit?debt/c.limit*100:0)}%"></div></div><div class="splitline meta muted"><span>Comprometido ${money(debt)}</span><span>Limite ${money(c.limit)}</span></div><div class="actions sectiongap">${button('Nova compra','new-purchase','plus','primary',c.id)}${button('Ver fatura','invoice','cards','',c.id)}${button('Editar','edit-card','edit','subtle small',c.id)}${button('','delete-card','trash','subtle small danger',c.id)}</div><div class="sectiongap"><span class="pill ${inv.total&&inv.due===0?'green':''}">${inv.total===0?'Nenhuma parcela neste mês':inv.due===0?'Fatura paga':'Em aberto: '+money(inv.due)}</span></div></div></section>`}).join('')}</div><div class="notice sectiongap">No painel, despesas de cartão seguem o mês da fatura. O patrimônio desconta toda a dívida das compras já feitas, incluindo parcelas futuras.</div>`:`<section class="panel">${empty('Seu cartão, sem fórmulas complicadas','Defina limite, fechamento e vencimento. O sistema distribui as compras em parcelas.','new-card','Adicionar cartão','cards')}</section>`}
function fixedPage(){const total=state.recurring.reduce((n,r)=>n+recurringExpected(r),0),paid=state.recurring.reduce((n,r)=>n+recurringPayments(r).reduce((a,t)=>a+t.amount,0),0);return `<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('Previsto no mês',total,'Compromissos cadastrados','fixed')}${metric('Previsto já quitado',paid,'Pagamentos confirmados','check')}${metric('Ainda previsto',Math.max(0,total-paid),'Confirme quando efetuar o pagamento','accounts')}</div><section class="panel">${state.recurring.length?`<div class="tablewrap"><table><thead><tr><th>Compromisso</th><th>Quando</th><th>Valor previsto</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${[...state.recurring].sort((a,b)=>(a.schedule==='flexible'?99:a.day)-(b.schedule==='flexible'?99:b.day)).map(r=>{const payments=recurringPayments(r),paid=payments[0],pending=recurringPending(r),expected=recurringExpected(r);return `<tr><td>${esc(r.name)}<div class="hint">${esc(categoryName(r.categoryId))}</div></td><td>${r.schedule==='flexible'?`${recurringOccurrences(r)}x no mês` : shortDate(dateAt(month,r.day))}</td><td>${money(expected)}${r.schedule==='flexible'?`<div class="hint">${money(r.amount)} por vez</div>`:''}</td><td><span class="pill ${!pending?'green':r.schedule==='due'&&dateAt(month,r.day)<today()?'red':''}">${r.schedule==='flexible'?(pending?`${payments.length}/${recurringOccurrences(r)} realizados`:'Concluído no mês'):paid?'Pago em '+shortDate(paid.date):dateAt(month,r.day)<today()?'Vencimento passado':'Pendente'}</span></td><td><div class="actions">${pending?button(r.schedule==='flexible'?'Registrar vez':'Confirmar pagamento','pay-fixed','check','small',r.id):button('Ver lançamento','edit-tx','right','small',paid?.id)}${button('','edit-fixed','edit','subtle small',r.id)}${button('','delete-fixed','trash','subtle small danger',r.id)}</div></td></tr>`}).join('')}</tbody></table></div>`:empty('Mais clareza para todo mês','Cadastre uma vez. Confirme o pagamento quando ele acontecer.','new-fixed','Adicionar gasto fixo','fixed')}</section><p class="hint">Use “Com vencimento” para assinaturas e contas. Para gastos como corte de cabelo, escolha “Sem vencimento” e informe quantas vezes pretende realizar no mês. O sistema só registra cada pagamento quando você confirmar.</p>`}

function goalsPage(){const statuses={planned:'Planejado',paid:'Pago',cancelled:'Desistido'};return state.goals.length?`<div class="three">${state.goals.map(g=>`<section class="card"><div class="card-top"><span class="goal-project">${esc(g.project||'Pessoal')}</span><span class="pill ${g.status==='paid'?'green':''}">${statuses[g.status]}</span></div><h2>${esc(g.name)}</h2><p class="meta muted">${esc(g.description||'Seu próximo plano.')}</p><div class="card-amount">${money(g.target)}</div><div class="meta muted">Custo previsto</div><div class="progress"><div style="width:${Math.min(100,g.saved/g.target*100)}%"></div></div><div class="splitline meta"><span>${money(g.saved)} planejados</span><strong>${Math.round(g.saved/g.target*100)}%</strong></div><div class="splitline meta muted"><span>Prioridade ${esc(g.priority)}</span><span>Impacto ${esc(g.impact||3)}/5</span></div>${g.dueDate?`<p class="hint">Entrega prevista: ${shortDate(g.dueDate)}</p>`:''}${g.url&&/^https?:\/\//i.test(g.url)?`<p><a href="${esc(g.url)}" target="_blank" rel="noopener noreferrer" class="meta">Link de compra ↗</a></p>`:''}<div class="actions">${button('Editar objetivo','edit-goal','edit','small',g.id)}${button('','delete-goal','trash','subtle small danger',g.id)}</div></section>`).join('')}</div><p class="hint">O valor planejado do objetivo é apenas um acompanhamento. Para separar dinheiro de verdade, faça uma transferência para uma conta de reserva.</p>`:`<section class="panel">${empty('Dê um lugar aos seus planos','Organize compras por projeto, prioridade, impacto e custo.','new-goal','Criar objetivo','goals')}</section>`}
function salaryPage(){const v=state.salary;return `<div class="two"><section class="panel"><div class="panelhead"><h2>Tempo e remuneração</h2></div><form id="salary-form" class="panelbody"><div class="formgrid">${field('hours','Horas trabalhadas',v.hours,'number','required min="0" max="10000" step="1"')}${field('minutes','Minutos adicionais',v.minutes,'number','required min="0" max="59" step="1"')}<div class="span2">${field('rate','Valor por hora (R$)',moneyInput(v.rate),'number','required min="0" step="0.01"')}</div>${field('first','Primeiro destino',v.first,'text','required maxlength="60"')}${field('second','Segundo destino',v.second,'text','required maxlength="60"')}<div class="span2">${field('percent','Percentual para o primeiro destino (%)',v.percent,'number','required min="0" max="100" step="0.1"')}</div></div><div class="form-error" role="alert"></div><button type="submit" class="primary">Salvar cálculo</button></form></section><section><div class="salary-total"><div class="meta">SALÁRIO CALCULADO</div><div id="salary-result"></div></div><div class="notice">Os percentuais sempre completam 100%. Este cálculo não movimenta suas contas automaticamente.</div>${button('Registrar como receita','salary-income','plus')}</section></div>`}
function salaryData(form){return {hours:Number(form.get('hours')),minutes:Number(form.get('minutes')),rate:cents(form.get('rate')),first:form.get('first').trim(),second:form.get('second').trim(),percent:Number(form.get('percent'))}}
function wireSalary(){const f=document.querySelector('#salary-form');const update=()=>{const v=salaryData(new FormData(f)),s=salaryCalc(v);document.querySelector('#salary-result').innerHTML=`<div class="card-amount">${money(s.total)}</div><div class="splitline"><span>${esc(v.first)} · ${v.percent}%</span><strong>${money(s.first)}</strong></div><div class="splitline"><span>${esc(v.second)} · ${Math.round((100-v.percent)*100)/100}%</span><strong>${money(s.second)}</strong></div>`};f.oninput=update;update();f.onsubmit=async e=>{e.preventDefault();try{await commit(s=>s.salary=salaryData(new FormData(f)),'Cálculo salvo')}catch(err){f.querySelector('.form-error').textContent=err.message}}}
const widgetNames={flow:'Entradas e despesas',accounts:'Onde está seu dinheiro',recent:'Últimos lançamentos',fixed:'Compromissos do mês'};
function settingsPage(){return `<div class="two"><section class="panel"><div class="panelhead"><h2>Aparência e painel</h2></div><div class="panelbody"><div class="settings-row"><div><strong>Cor de destaque</strong><p>Botões, indicadores e destaques.</p></div><input type="color" aria-label="Cor de destaque" value="${state.settings.accent}" id="accent"></div><div class="settings-row"><div><strong>Tabelas compactas</strong><p>Mais lançamentos no mesmo espaço.</p></div><input type="checkbox" aria-label="Tabelas compactas" id="density" ${state.settings.density==='compact'?'checked':''}></div><h3 class="sectiongap">Blocos da visão geral</h3>${[...state.settings.widgets,...Object.keys(widgetNames).filter(k=>!state.settings.widgets.includes(k))].map(k=>`<div class="settings-row"><label class="checkline"><input type="checkbox" data-widget="${k}" ${state.settings.widgets.includes(k)?'checked':''}> ${widgetNames[k]}</label><div class="reorder">${button('','widget-up','up','subtle small',k)}${button('','widget-down','down','subtle small',k)}</div></div>`).join('')}</div></section><section class="panel"><div class="panelhead"><h2>Categorias</h2>${button('Adicionar','new-category','plus','small')}</div><div class="panelbody" style="max-height:450px;overflow:auto">${state.categories.map(c=>`<div class="settings-row"><span>${esc(c.name)}</span><div class="actions">${button('','edit-category','edit','subtle small',c.id)}${button('','delete-category','trash','subtle small danger',c.id)}</div></div>`).join('')}</div></section><section class="panel"><div class="panelhead"><h2>Campos dos lançamentos</h2>${button('Novo campo','new-field','plus','small')}</div><div class="panelbody"><p class="meta muted">Adicione informações que fazem sentido para você. Os campos aparecem no formulário e na tabela.</p>${state.settings.fields.length?state.settings.fields.map(f=>`<div class="settings-row"><span>${esc(f.name)} <small class="muted">· ${{text:'Texto',number:'Número',date:'Data'}[f.type]}</small></span><div>${button('','edit-field','edit','subtle small',f.id)}${button('','delete-field','trash','subtle small danger',f.id)}</div></div>`).join(''):'<p class="hint">Nenhum campo extra por enquanto.</p>'}</div></section><section class="panel"><div class="panelhead"><h2>Seus dados, com você</h2>${icon('lock')}</div><div class="panelbody"><p class="meta muted">Somente o seu cofre é aberto com sua senha. Outros usuários locais começam com um espaço vazio.</p><div class="actions">${button('Exportar backup','backup','download')}${button('Exportar migração CSV','migration-csv','download')}${button('Restaurar backup','restore','transactions')}</div><p class="hint">O backup também é criptografado. Guarde o arquivo e sua senha: limpar os dados do navegador remove o cofre local. Não há sincronização com o Notion.</p><div class="notice sectiongap">Esta é a versão local. Contas na internet, recuperação de senha e sincronização entre computadores ainda não estão disponíveis.</div></div></section></div>`}
function txForm(id,defaults={}){if(!state.accounts.length){accountForm();toast('Primeiro, cadastre uma conta.');return}const old=state.transactions.find(t=>t.id===id);const t=old||{type:'expense',description:'',amount:0,date:today(),accountId:state.accounts[0].id,categoryId:'',notes:'',extra:{},...defaults};const extras=state.settings.fields.map(f=>field('extra-'+f.id,esc(f.name),t.extra?.[f.id]||'',f.type,f.type==='number'?'step="any"':'maxlength="500"')).join('');dialog(old?'Editar lançamento':'Novo lançamento',`${t.recurringId?'<div class="notice">Este lançamento confirma um gasto fixo. Ao excluí-lo, o compromisso volta a ficar pendente.</div>':''}<div class="formgrid">${select('type','Tipo',[['expense','Despesa'],['income','Receita'],['transfer','Transferência']],t.type)}${field('amount','Valor (R$)',t.amount?moneyInput(t.amount):'','number','required min="0.01" step="0.01"')}<div class="span2">${field('description','Descrição',t.description,'text','required maxlength="180" placeholder="Ex.: compras no mercado"')}</div>${field('date','Data',t.date,'date','required')}${select('accountId','Conta de origem / recebimento',acOpts(),t.accountId,'required')}<div id="tx-destination" class="span2" ${t.type!=='transfer'?'hidden':''}>${select('toAccountId','Conta de destino',[['','Selecione'],...acOpts()],t.toAccountId||'')}</div><div id="tx-category" class="span2" ${t.type==='transfer'?'hidden':''}>${select('categoryId','Categoria',catOpts(),t.categoryId)}</div>${extras}<div class="field span2"><label for="f-notes">Observação</label><textarea id="f-notes" name="notes" maxlength="2000">${esc(t.notes)}</textarea></div></div>`,true,async f=>{const type=f.get('type'),accountId=f.get('accountId'),toAccountId=f.get('toAccountId');if(type==='transfer'&&(!toAccountId||toAccountId===accountId))throw Error('Escolha duas contas diferentes.');if(old?.recurringId&&type!=='expense')throw Error('Um pagamento de gasto fixo deve continuar sendo uma despesa.');const value={...t,id:old?.id||uid(),type,accountId,toAccountId:type==='transfer'?toAccountId:'',categoryId:type==='transfer'?'':f.get('categoryId'),description:f.get('description').trim(),amount:cents(f.get('amount')),date:f.get('date'),notes:f.get('notes'),extra:Object.fromEntries(state.settings.fields.map(x=>[x.id,f.get('extra-'+x.id)]))};if(!value.description)throw Error('Informe uma descrição.');await commit(s=>{if(old)s.transactions[s.transactions.findIndex(x=>x.id===id)]=value;else s.transactions.push(value)},'Lançamento salvo')});document.querySelector('#f-type').onchange=e=>{document.querySelector('#tx-destination').hidden=e.target.value!=='transfer';document.querySelector('#tx-category').hidden=e.target.value==='transfer'};}
function accountForm(id){const a=state.accounts.find(a=>a.id===id)||{name:'',kind:'checking',opening:0,openingDate:today(),color:'#147d64'};dialog(id?'Editar conta':'Nova conta',`${field('name','Nome da conta',a.name,'text','required maxlength="60" placeholder="Ex.: Nubank, C6, Reserva de emergência"')}<div class="formgrid">${select('kind','Tipo',Object.entries(kindName),a.kind)}${field('color','Cor',a.color,'color')}${field('opening','Saldo inicial (R$)',moneyInput(a.opening),'number','required step="0.01"')}${field('openingDate','Data do saldo inicial',a.openingDate,'date','required')}</div><p class="hint">Use o saldo anterior ao primeiro lançamento que você vai registrar. Reservas e garantias não entram no saldo disponível.</p>`,true,async f=>{const v={id:id||uid(),name:f.get('name').trim(),kind:f.get('kind'),color:f.get('color'),opening:cents(f.get('opening')),openingDate:f.get('openingDate')};if(!v.name)throw Error('Informe um nome.');await commit(s=>{if(id)s.accounts[s.accounts.findIndex(x=>x.id===id)]=v;else s.accounts.push(v)})})}
function cardForm(id){const c=state.cards.find(c=>c.id===id)||{name:'',limit:0,closing:20,due:28,color:'#162c42'};dialog(id?'Editar cartão':'Novo cartão',`${field('name','Nome do cartão',c.name,'text','required maxlength="60" placeholder="Ex.: Meu cartão C6"')}<div class="formgrid">${field('limit','Limite total (R$)',moneyInput(c.limit),'number','required min="0" step="0.01"')}${field('color','Cor do cartão',c.color,'color')}${field('closing','Dia do fechamento',c.closing,'number','required min="1" max="31"')}${field('due','Dia do vencimento',c.due,'number','required min="1" max="31"')}</div><p class="hint">Compras no dia do fechamento entram no próximo ciclo. Você pode ajustar a primeira fatura de cada compra. Alterar estes dias não move parcelas já cadastradas.</p>`,true,async f=>{const v={id:id||uid(),name:f.get('name').trim(),limit:cents(f.get('limit')),color:f.get('color'),closing:Number(f.get('closing')),due:Number(f.get('due'))};if(!v.name)throw Error('Informe o nome do cartão.');await commit(s=>{if(id)s.cards[s.cards.findIndex(x=>x.id===id)]=v;else s.cards.push(v)})})}
function purchaseForm(cardId,id){const c=state.cards.find(c=>c.id===cardId);const old=state.purchases.find(p=>p.id===id);if(old&&installments(old).some(i=>invoice(state,cardId,i.month).paid>0)){toast('Esta compra tem fatura paga. Desfaça o pagamento antes de editar.');return}const p=old||{description:'',amount:0,date:today(),count:1,firstMonth:firstInvoice(today(),c),categoryId:'',notes:''};dialog(old?'Editar compra':'Nova compra no cartão',`<div class="notice">${esc(c.name)} · Limite disponível: ${money(Math.max(0,cardLimit(state,c)-outstanding(state,c.id)))}</div>${field('description','Descrição',p.description,'text','required maxlength="180"')}<div class="formgrid">${field('amount','Valor total da compra (R$)',p.amount?moneyInput(p.amount):'','number','required min="0.01" step="0.01"')}${field('count','Número de parcelas',p.count,'number','required min="1" max="120"')}${field('date','Data da compra',p.date,'date','required')}${field('firstMonth','Primeira fatura',p.firstMonth,'month','required')}<div class="span2">${select('categoryId','Categoria',catOpts('expense'),p.categoryId)}</div></div><p class="hint">O valor total será distribuído em centavos, sem perder a soma da compra. A primeira fatura é editável para acompanhar a regra do seu banco.</p>`,true,async f=>{const v={...p,id:id||uid(),cardId,description:f.get('description').trim(),amount:cents(f.get('amount')),count:Number(f.get('count')),date:f.get('date'),firstMonth:f.get('firstMonth'),categoryId:f.get('categoryId')};if(!v.description)throw Error('Informe uma descrição.');if(installments(v).some(i=>invoice(state,cardId,i.month).paid>0))throw Error('Existe pagamento em uma das faturas de destino. Desfaça-o antes de alterar as parcelas.');await commit(s=>{if(id)s.purchases[s.purchases.findIndex(x=>x.id===id)]=v;else s.purchases.push(v)},'Compra e parcelas salvas')});document.querySelector('#f-date').onchange=e=>{if(e.target.value)document.querySelector('#f-firstMonth').value=firstInvoice(e.target.value,c)}}
function invoiceDialog(cardId){const c=state.cards.find(c=>c.id===cardId),i=invoice(state,cardId,month),payments=state.payments.filter(p=>p.cardId===cardId&&p.month===month);modal.innerHTML=`<div class="modalhead"><div><h2>${esc(c.name)} · ${monthName(month)}</h2><p class="hint">Vence em ${shortDate(dateAt(month,c.due))}</p></div>${button('','close','close','subtle')}</div><div class="modalbody"><div class="splitline"><span>Total da fatura</span><strong>${money(i.total)}</strong></div><div class="splitline"><span>Em aberto</span><strong>${money(i.due)}</strong></div>${i.items.length?i.items.map(p=>`<div class="settings-row"><div><strong class="meta">${esc(p.description)}</strong><p>Parcela ${p.number}/${p.count} · ${money(p.amount)}</p></div><div class="actions">${button('','edit-purchase','edit','subtle small',p.purchaseId)}${button('','delete-purchase','trash','subtle small danger',p.purchaseId)}</div></div>`).join(''):empty('Nenhuma parcela neste mês','Mude o mês para consultar outras faturas.')}<div class="sectiongap">${payments.map(p=>`<div class="notice">Pago em ${shortDate(p.date)} · ${esc(accountName(p.accountId))} · ${money(p.amount)} ${button('Desfazer','delete-payment','','small',p.id)}</div>`).join('')}</div><div class="modalfoot">${button('Fechar','close')}${i.due?button('Pagar fatura','pay-invoice','check','primary',cardId):''}</div></div>`;modal.showModal()}
function payInvoice(cardId){if(!state.accounts.length){modal.close();accountForm();return}const i=invoice(state,cardId,month);modal.close();dialog('Pagar fatura',`<div class="notice">${esc(state.cards.find(c=>c.id===cardId).name)} · ${monthName(month)}<br>Total a pagar: <strong>${money(i.due)}</strong></div>${select('accountId','Pagar com qual conta?',acOpts())}${field('date','Data do pagamento',today(),'date','required')}<p class="hint">O pagamento reduz o saldo da conta e a dívida do cartão. Não cria uma segunda despesa.</p>`,true,async f=>{await commit(s=>{const fresh=invoice(s,cardId,month);if(!fresh.due)throw Error('Esta fatura já foi paga.');s.payments.push({id:uid(),cardId,month,amount:fresh.due,accountId:f.get('accountId'),date:f.get('date')})},'Fatura paga')},'Confirmar pagamento')}
function fixedForm(id){const r=state.recurring.find(r=>r.id===id)||{name:'',amount:0,day:10,accountId:'',categoryId:'',schedule:'due',occurrences:1};dialog(id?'Editar gasto fixo':'Novo gasto fixo',`${field('name','Descrição',r.name,'text','required maxlength="180"')}<div class="formgrid"><div class="field"><label for="f-schedule-select">Tipo de compromisso</label><select id="f-schedule-select" name="schedule"><option value="due" ${r.schedule!=='flexible'?'selected':''}>Com vencimento</option><option value="flexible" ${r.schedule==='flexible'?'selected':''}>Sem vencimento · por quantidade no mês</option></select></div>${field('amount',r.schedule==='flexible'?'Valor por vez (R$)':'Valor previsto (R$)',r.amount?moneyInput(r.amount):'','number','required min="0.01" step="0.01"')}<div id="fixed-day-field" ${r.schedule==='flexible'?'hidden':''}>${field('day','Dia do vencimento',r.day,'number','required min="1" max="31"')}</div><div id="fixed-occurrences-field" ${r.schedule!=='flexible'?'hidden':''}>${field('occurrences','Quantidade no mês',r.occurrences||2,'number','required min="1" max="31"')}</div>${select('accountId','Conta preferida',[['','Escolher no pagamento'],...acOpts()],r.accountId)}${select('categoryId','Categoria',catOpts('expense'),r.categoryId)}</div><p id="fixed-schedule-hint" class="hint">${r.schedule==='flexible'?'Não há data fixa. Registre cada vez que acontecer, até completar a quantidade do mês.':'Aparece nos próximos vencimentos até você confirmar o pagamento.'}</p>`,true,async f=>{const schedule=f.get('schedule')==='flexible'?'flexible':'due',occurrences=schedule==='flexible'?Number(f.get('occurrences')):1,day=schedule==='due'?Number(f.get('day')):0;const v={id:id||uid(),name:f.get('name').trim(),amount:cents(f.get('amount')),day,occurrences,schedule,accountId:f.get('accountId'),categoryId:f.get('categoryId')};if(!v.name)throw Error('Informe uma descrição.');if(schedule==='flexible'&&(!Number.isInteger(occurrences)||occurrences<1||occurrences>31))throw Error('Informe uma quantidade válida para o mês.');await commit(s=>{if(id)s.recurring[s.recurring.findIndex(x=>x.id===id)]=v;else s.recurring.push(v)},'Gasto fixo salvo')});const scheduleSelect=document.querySelector('#f-schedule-select'),dayField=document.querySelector('#fixed-day-field'),occField=document.querySelector('#fixed-occurrences-field'),dayInput=document.querySelector('#f-day'),occInput=document.querySelector('#f-occurrences'),amountLabel=document.querySelector('label[for="f-amount"]'),hint=document.querySelector('#fixed-schedule-hint');const sync=()=>{const flexible=scheduleSelect?.value==='flexible';if(dayField)dayField.hidden=flexible;if(occField)occField.hidden=!flexible;if(dayInput)dayInput.disabled=flexible;if(occInput)occInput.disabled=!flexible;if(amountLabel)amountLabel.textContent=flexible?'Valor por vez (R$)':'Valor previsto (R$)';if(hint)hint.textContent=flexible?'Não há data fixa. Registre cada vez que acontecer, até completar a quantidade do mês.':'Aparece nos próximos vencimentos até você confirmar o pagamento.'};scheduleSelect?.addEventListener('change',sync);sync()}
function payFixed(id){const r=state.recurring.find(r=>r.id===id);if(!r||!recurringPending(r)){toast('Este compromisso já foi concluído neste mês.');return}if(!state.accounts.length){accountForm();toast('Cadastre uma conta para registrar o pagamento.');return}const next=recurringPayments(r).length+1;dialog(recurringFlexible(r)?'Registrar ocorrência':'Confirmar pagamento',`<div class="notice">${esc(r.name)} · competência ${monthName(month)}${recurringFlexible(r)?` · ocorrência ${next} de ${recurringOccurrences(r)}`:''}</div>${field('amount','Valor pago (R$)',moneyInput(r.amount),'number','required min="0.01" step="0.01"')}${select('accountId','Conta de pagamento',acOpts(),r.accountId)}${field('date','Data do pagamento',today(),'date','required')}`,true,async f=>{await commit(s=>{const count=s.transactions.filter(t=>t.recurringId===id&&t.recurringMonth===month).length;if((r.schedule==='flexible'&&count>=recurringOccurrences(r))||(r.schedule!=='flexible'&&count>0))throw Error('Este compromisso já foi concluído neste mês.');s.transactions.push({id:uid(),type:'expense',description:r.name,amount:cents(f.get('amount')),date:f.get('date'),accountId:f.get('accountId'),categoryId:r.categoryId,notes:'',extra:{},recurringId:id,recurringMonth:month})},'Pagamento registrado')},recurringFlexible(r)?'Registrar':'Confirmar pagamento')}

function goalForm(id){const g=state.goals.find(g=>g.id===id)||{name:'',target:0,saved:0,project:'Pessoal',priority:'Média',impact:3,status:'planned',description:'',url:'',dueDate:''};dialog(id?'Editar objetivo':'Novo objetivo',`${field('name','Objetivo',g.name,'text','required maxlength="180"')}<div class="formgrid">${field('target','Custo previsto (R$)',g.target?moneyInput(g.target):'','number','required min="0.01" step="0.01"')}${field('saved','Valor planejado (R$)',moneyInput(g.saved),'number','required min="0" step="0.01"')}${field('project','Projeto',g.project,'text','maxlength="60"')}${select('priority','Prioridade',['Ideia','Baixa','Média','Alta','Urgente'].map(x=>[x,x]),g.priority)}${select('impact','Impacto',[1,2,3,4,5].map(x=>[x,x+' de 5']),g.impact)}${select('status','Situação',[['planned','Planejado'],['paid','Pago'],['cancelled','Desistido']],g.status)}${field('purchaseBy','Data prevista de aquisição',g.purchaseBy||g.dueDate||'','date')}<p class="hint span2">Escolha o dia em que pretende comprar. Se ainda não souber, deixe em branco.</p>${field('url','Link de compra',g.url,'url','maxlength="2000"')}<div class="span2">${field('description','Descrição / observações',g.description,'text','maxlength="1000"')}</div></div><p class="hint">Este acompanhamento não movimenta dinheiro automaticamente.</p>`,true,async f=>{const v={id:id||uid(),name:f.get('name').trim(),target:cents(f.get('target')),saved:cents(f.get('saved')),project:f.get('project'),priority:f.get('priority'),impact:Number(f.get('impact')),status:f.get('status'),purchaseBy:f.get('purchaseBy'),url:f.get('url'),description:f.get('description')};if(!v.name)throw Error('Informe um objetivo.');if(v.url&&!/^https?:\/\//i.test(v.url))throw Error('Use um link iniciado por https:// ou http://.');await commit(s=>{if(id)s.goals[s.goals.findIndex(x=>x.id===id)]=v;else s.goals.push(v)})})}
function categoryForm(id){const c=state.categories.find(c=>c.id===id);dialog(c?'Editar categoria':'Nova categoria',field('name','Nome',c?.name||'','text','required maxlength="60"'),true,async f=>{const name=f.get('name').trim();if(!name)throw Error('Informe um nome.');if(state.categories.some(c=>c.id!==id&&c.name.toLowerCase()===name.toLowerCase()))throw Error('Já existe uma categoria com esse nome.');await commit(s=>{if(id)s.categories.find(c=>c.id===id).name=name;else s.categories.push({id:uid(),name})})})}
function customFieldForm(id){const f=state.settings.fields.find(f=>f.id===id);dialog(f?'Editar campo':'Novo campo',`${field('name','Nome do campo',f?.name||'','text','required maxlength="60"')}${select('type','Tipo',[['text','Texto'],['number','Número'],['date','Data']],f?.type||'text',id?'disabled':'')}`,true,async d=>{const name=d.get('name').trim();if(!name)throw Error('Informe o nome do campo.');await commit(s=>{if(id)s.settings.fields.find(f=>f.id===id).name=name;else s.settings.fields.push({id:uid(),name,type:d.get('type')})})})}
function remove(kind,id){const groups={tx:'transactions',account:'accounts',card:'cards',fixed:'recurring',goal:'goals',category:'categories',purchase:'purchases',payment:'payments'};const group=groups[kind];const linkedInvestments=kind==='account'?state.investments.filter(i=>i.accountId===id):[];const linkedInvestment=linkedInvestments[0]||null;const linkedTx=kind==='account'?state.transactions.filter(t=>t.accountId===id||t.toAccountId===id):[];if(kind==='account'){if(linkedInvestments.length>1){toast('Esta conta tem mais de um investimento vinculado. Edite os vínculos antes de excluí-la.');return}const unsafe=linkedTx.some(t=>!(linkedInvestment&&t.type==='transfer'&&t.toAccountId===id));if((unsafe)||state.payments.some(p=>p.accountId===id)||state.recurring.some(r=>r.accountId===id)){toast('Esta conta tem vínculos. Edite os lançamentos e gastos fixos antes de excluí-la.');return}}if(kind==='card'&&state.purchases.some(p=>p.cardId===id)){toast('Exclua as compras deste cartão antes de removê-lo.');return}if(kind==='category'&&[...state.transactions,...state.purchases,...state.recurring].some(t=>t.categoryId===id)){toast('Esta categoria está em uso. Altere os registros vinculados antes de excluí-la.');return}if(kind==='purchase'){const p=state.purchases.find(p=>p.id===id);if(installments(p).some(i=>invoice(state,p.cardId,i.month).paid>0)){toast('Desfaça os pagamentos das faturas desta compra antes de excluí-la.');return}}const item=kind==='field'?state.settings.fields.find(f=>f.id===id):state[group].find(x=>x.id===id);modal.close();dialog('Confirmar exclusão',`<p>Excluir <strong>${esc(item?.name||item?.description||(kind==='payment'?'o pagamento desta fatura':'este registro'))}</strong>?</p><p class="hint">${linkedInvestment?'Os lançamentos de transferência serão preservados e passarão a apontar para o investimento vinculado.':''}${kind==='purchase'?'Todas as parcelas desta compra serão removidas.':kind==='payment'?'A fatura ficará em aberto e o valor voltará ao saldo da conta.':kind==='fixed'?'Os pagamentos já feitos serão preservados.':kind==='field'?'O campo e seus valores serão removidos de todos os lançamentos.':'Os saldos e resumos serão recalculados.'}</p>`,true,async()=>{await commit(s=>{if(kind==='account'&&linkedInvestment){s.transactions.forEach(t=>{if(t.type==='transfer'&&t.toAccountId===id){t.toAccountId='';t.toInvestmentId=linkedInvestment.id}});s.investments.forEach(i=>{if(i.accountId===id)i.accountId=''})}if(kind==='field'){s.settings.fields=s.settings.fields.filter(f=>f.id!==id);s.transactions.forEach(t=>{if(t.extra)delete t.extra[id]})}else s[group]=s[group].filter(x=>x.id!==id)},'Registro excluído')},'Excluir')}
function exportBackup(){if(session.demo){toast('Entre no seu cofre para exportar seus dados.');return}const blob=new Blob([vault.backup(session)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`orbe-${today()}.orbe`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Backup exportado. Guarde também a senha do cofre.')}
function exportMigrationCsv(){if(session.demo){toast('Entre no seu cofre para exportar seus dados.');return}const accountNameById=id=>state.accounts.find(a=>a.id===id)?.name||'',categoryNameById=id=>state.categories.find(c=>c.id===id)?.name||'',cardNameById=id=>state.cards.find(c=>c.id===id)?.name||'',investmentNameById=id=>state.investments.find(i=>i.id===id)?.name||'',signed=(type,amount)=>type==='expense'?-amount:amount,cell=v=>{const text=String(v??'');return /[;"\n]/.test(text)?`"${text.replace(/"/g,'""')}"`:text},rows=[['Descrição','Valor','Tipo','Data','Vencimento','Categoria','Subcategoria','Conta','Conta de destino','Cartão de crédito','Observações','Estabelecimento']];state.transactions.forEach(t=>{const destination=t.toInvestmentId?`Investimentos · ${investmentNameById(t.toInvestmentId)}`:accountNameById(t.toAccountId);rows.push([t.description,(signed(t.type,t.amount)/100).toFixed(2).replace('.',','),t.type==='income'?'Receita':t.type==='transfer'?'Transferência':'Despesa',t.date,'',categoryNameById(t.categoryId),'',accountNameById(t.accountId),destination,cardNameById(t.paymentCardId),t.notes||'',t.description])});state.purchases.forEach(p=>installments(p).forEach(i=>{const date=`${i.month}-01`;rows.push([`${i.description} (${i.number}/${i.count})`,(-i.amount/100).toFixed(2).replace('.',','),'Despesa',date,i.month,categoryNameById(i.categoryId),'', '', '',cardNameById(i.cardId),`${p.notes||''}${p.notes?' · ':''}Compra parcelada`,p.description])}));const csv='\uFEFF'+rows.map(row=>row.map(cell).join(';')).join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`minhas-financas-migracao-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast(`${rows.length-1} registros preparados para importar`)}
function restore(fromAuth=false){if(session?.demo){toast('Crie seu usuário para restaurar um backup.');return}dialog('Restaurar backup',`${field('file','Arquivo de backup (.orbe)','','file','accept=".orbe,application/json" required')}${field('backupPassword','Senha usada no backup','','password','required autocomplete="off"')}${fromAuth?field('name','Nome do usuário restaurado','','text','required maxlength="60"'):''}<div class="notice warn">${fromAuth?'Será criado um novo cofre, usando a senha do backup.':'A restauração substitui os dados do usuário atual. Exporte um backup antes de continuar.'}</div><label class="checkline"><input name="confirm" type="checkbox" required> Entendi e quero restaurar os dados.</label>`,true,async f=>{const file=f.get('file');if(file.size>30*1024*1024)throw Error('O arquivo é muito grande (máximo 30 MB).');const data=await vault.readBackup(await file.text(),f.get('backupPassword'));if(fromAuth){session=await vault.create(f.get('name').trim()||'Meu espaço',f.get('backupPassword'),data);state=session.data;page=readLastPage();syncPageHistory(true);render()}else await commit(s=>{for(const k of Object.keys(s))delete s[k];Object.assign(s,data)},'Backup restaurado')},'Restaurar')}
async function action(name,id){if(busy){toast('Aguarde o salvamento.');return}switch(name){case'close':modal.close();break;case'demo':{const {demo}=await import('./demo.mjs');state=migrate(demo());session={demo:true,record:{name:'Demonstração'},data:state};page='dashboard';month=currentMonth();render();break}case'toggle-auth':await auth(authMode==='create'?'login':'create');break;case'restore-auth':restore(true);break;case'logout':modal.close();await vault.forget();await auth();break;case'nav':search='';filter='all';accountFilter='all';navigatePage(id);break;case'clear-goal-filters':goalSearch='';goalProjectFilter='all';goalStatusFilter='active';goalPriorityFilter='all';goalFocusFilter='all';render();break;case'prev-month':month=addMonth(month,-1);render();break;case'next-month':month=addMonth(month,1);render();break;case'new-tx':txForm();break;case'edit-tx':txForm(id);break;case'account-tx':txForm(null,{accountId:id});break;case'new-account':accountForm();break;case'edit-account':accountForm(id);break;case'new-card':cardForm();break;case'edit-card':cardForm(id);break;case'new-purchase':purchaseForm(id);break;case'edit-purchase':{const p=state.purchases.find(p=>p.id===id);modal.close();purchaseForm(p.cardId,id);break}case'invoice':invoiceDialog(id);break;case'pay-invoice':payInvoice(id);break;case'new-fixed':fixedForm();break;case'edit-fixed':fixedForm(id);break;case'pay-fixed':payFixed(id);break;case'new-goal':goalForm();break;case'edit-goal':goalForm(id);break;case'new-category':categoryForm();break;case'edit-category':categoryForm(id);break;case'new-field':customFieldForm();break;case'edit-field':customFieldForm(id);break;case'backup':exportBackup();break;case'migration-csv':exportMigrationCsv();break;case'restore':restore();break;case'change-password':changePasswordForm();break;case'salary-income':{const f=document.querySelector('#salary-form');if(!f.reportValidity())return;const v=salaryData(new FormData(f));const test=structuredClone(state);test.salary=v;validate(test);const calc=salaryCalc(v);if(calc.total<=0){toast('Informe horas e valor por hora antes de lançar.');return}txForm(null,{type:'income',description:'Salário',amount:calc.total,notes:`${v.first}: ${money(calc.first)}; ${v.second}: ${money(calc.second)}`});break}case'widget-up':case'widget-down':await commit(s=>{const a=s.settings.widgets,i=a.indexOf(id),j=i+(name==='widget-up'?-1:1);if(i>=0&&j>=0&&j<a.length)[a[i],a[j]]=[a[j],a[i]]});break;default:if(name.startsWith('delete-'))remove(name.slice(7),id)}}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)action(b.dataset.action,b.dataset.id).catch(err=>toast(err.message))});
 document.addEventListener('change',e=>{if(!state)return;const el=e.target;if(el.id==='accent')commit(s=>s.settings.accent=el.value).catch(err=>toast(err.message));if(el.id==='density')commit(s=>s.settings.density=el.checked?'compact':'normal').catch(err=>toast(err.message));if(el.id==='theme-dark')commit(s=>s.settings.theme=el.checked?'dark':'light').catch(err=>toast(err.message));if(el.id==='tx-filter'){filter=el.value;refreshTxTable()}if(el.id==='account-filter'){accountFilter=el.value;refreshTxTable()}if(el.id==='tx-period'){txRange=el.value==='all'?'all':'month';render()}if(el.id==='goal-project-filter'){goalProjectFilter=el.value;render()}if(el.id==='goal-status-filter'){goalStatusFilter=el.value;render()}if(el.id==='goal-priority-filter'){goalPriorityFilter=el.value;render()}if(el.id==='goal-focus-filter'){goalFocusFilter=el.value;render()}if(el.id==='goal-sort-select'){goalSort=el.value;goalSortDir='asc';render()}if(el.dataset.widget)commit(s=>{s.settings.widgets=el.checked?[...s.settings.widgets,el.dataset.widget]:s.settings.widgets.filter(w=>w!==el.dataset.widget)}).catch(err=>toast(err.message))});function syncHistoryPoint(point,active){const card=point?.closest?.('.analysis-history-card');if(!card)return;card.querySelectorAll('.analysis-history-detail').forEach(item=>{const match=active&&item.dataset.pointIndex===point.dataset.pointIndex;item.classList.toggle('is-active',match);if(match)item.scrollIntoView({block:'nearest'})})}
document.addEventListener('pointerover',e=>{const point=e.target.closest?.('.analysis-history-point');if(point)syncHistoryPoint(point,true)},true);
document.addEventListener('pointerout',e=>{const point=e.target.closest?.('.analysis-history-point');if(point&&!point.contains(e.relatedTarget))syncHistoryPoint(point,false)},true);
document.addEventListener('focusin',e=>{const point=e.target.closest?.('.analysis-history-point');if(point)syncHistoryPoint(point,true)},true);
document.addEventListener('focusout',e=>{const point=e.target.closest?.('.analysis-history-point');if(point)syncHistoryPoint(point,false)},true);
document.addEventListener('input',e=>{const el=e.target;if(el.id==='tx-search'){search=el.value;refreshTxTable()}if(el.id==='goal-search'){goalSearch=el.value;render();const next=document.querySelector('#goal-search');if(next){next.focus();next.setSelectionRange(goalSearch.length,goalSearch.length)}}if(el.id==='f-institution'){const list=document.querySelector('#investment-options');if(list)list.innerHTML=investmentOptionsFor(el.value).map(o=>`<option value="${esc(o)}"></option>`).join('')}});
 modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
 window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue=''}});
 if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'open_finance_section',title:'Abrir seção financeira',description:'Navega para uma seção do cofre desbloqueado, sem criar nem alterar registros.',inputSchema:{type:'object',properties:{section:{type:'string',enum:Object.keys(title)}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:true},execute:async({section})=>{if(!state)throw Error('Desbloqueie seu cofre primeiro.');if(!Object.hasOwn(title,section))throw Error('Seção inválida.');navigatePage(section);return {section,title:title[section]}}})}catch{}}
 auth().catch(err=>{app.innerHTML=`<div class="auth-form"><div><h1>Não foi possível abrir o cofre.</h1><p>${esc(err.message)}</p><p>Abra pelo endereço local em um navegador com armazenamento habilitado.</p></div></div>`});

/* Evolução do espaço: cartões, investimentos, projetos e preferências editáveis. */
const cardTypeName={credit:'Crédito',debit:'Débito',both:'Débito e crédito'};
const investmentTypeName={stock:'Ações',fund:'Fundos',fixed:'Renda fixa',crypto:'Cripto',other:'Outro'};const investmentOptionsByBank={c6:['CDB C6','CDB pós-fixado','LCI/LCA','Tesouro Direto','Fundos de investimento','Ações','FIIs'],nubank:['Caixinhas','Nu Reserva Imediata','CDB do Nubank','Tesouro Direto','Fundos de investimento','Ações'],inter:['CDB Inter','LCI/LCA','Tesouro Direto','Fundos de investimento','Ações','FIIs'],itau:['CDB Itaú','LCI/LCA','Tesouro Direto','Fundos de investimento','Ações','FIIs'],xp:['CDB','LCI/LCA','Tesouro Direto','Fundos de investimento','Ações','FIIs'],btg:['CDB BTG','LCI/LCA','Tesouro Direto','Fundos de investimento','Ações','FIIs']};const investmentOptionsFor=name=>{const key=String(name||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');const specific=Object.entries(investmentOptionsByBank).find(([bank])=>key.includes(bank))?.[1]||[];return [...new Set([...specific,'CDB','LCI/LCA','Tesouro Direto','Fundos de investimento','Ações','FIIs','ETFs','Cripto','Outro'])]};
function dueState(date){const d=Math.ceil((new Date(date+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000);return d<0?'late':d===0?'today':d<=5?'near':'normal'}
function dueLabel(state){return {late:'Atrasado',today:'Vence hoje',near:'Próximo do vencimento',normal:'Em dia'}[state]}
function alertItems(){const out=[];for(const c of state.cards.filter(c=>c.type!=='debit')){const d=dateAt(month,c.due),i=invoice(state,c.id,month);if(i.due)out.push({date:d,state:dueState(d),text:`Fatura ${c.name}`,detail:money(i.due)})}for(const r of state.recurring){if(r.schedule!=='flexible'&&recurringPending(r)){const d=dateAt(month,r.day);out.push({date:d,state:dueState(d),text:r.name,detail:money(r.amount)})}}return out.sort((a,b)=>a.date.localeCompare(b.date))}
function alertsPanel(){const items=alertItems();return `<section class="panel widget"><div class="panelhead"><h2>Próximos vencimentos</h2><span class="meta muted">${items.length} pendente${items.length===1?'':'s'}</span></div><div class="panelbody">${items.length?items.slice(0,5).map(x=>`<div class="settings-row"><div><strong>${esc(x.text)}</strong><p class="hint">${shortDate(x.date)} · ${esc(dueLabel(x.state))}</p></div><strong>${x.detail}</strong></div>`).join(''):'<p class="hint">Nenhum vencimento pendente neste período.</p>'}</div></section>`}
function investmentsPanel(){const total=investmentTotal(state,'current',today()),applied=investmentTotal(state,'applied'),yieldTotal=state.investments.reduce((n,i)=>n+investmentYield(i,today()),0);return `<section class="panel widget"><div class="panelhead"><h2>Investimentos</h2>${button('Ver investimentos','nav','right','small','investments')}</div><div class="panelbody"><div class="splitline"><span class="muted">Valor atual</span><strong>${money(total)}</strong></div><div class="splitline"><span class="muted">Total aplicado</span><span>${money(applied)}</span></div><div class="splitline"><span class="muted">Rendimento</span><span class="${yieldTotal>=0?'positive':'negative'}">${money(yieldTotal)}</span></div><p class="hint">${state.investments.length} investimento${state.investments.length===1?'':'s'} cadastrado${state.investments.length===1?'':'s'}.</p></div></section>`}
function goalsPanel(){const pending=state.goals.filter(g=>g.status!=='paid'&&g.status!=='cancelled');return `<section class="panel widget"><div class="panelhead"><h2>Objetivos</h2>${button('Ver objetivos','nav','right','small','goals')}</div><div class="panelbody">${pending.length?pending.slice(0,4).map(g=>`<div class="settings-row"><div><strong>${esc(g.name)}</strong><p class="hint">${esc(g.projectId?state.projects.find(p=>p.id===g.projectId)?.name||'Sem projeto':'Sem projeto')}</p></div><span>${money(g.saved)} / ${money(g.target)}</span></div>`).join(''):'<p class="hint">Nenhum objetivo em aberto.</p>'}</div></section>`}
function dashboardV2(){const s=summary(state,month);const widgets={flow:flowPanel,accounts:accountsPanel,recent:recentPanel,fixed:fixedPanel,alerts:alertsPanel,investments:investmentsPanel,goals:goalsPanel};const overview=state.settings.overview||{};const selected=state.settings.widgets.filter(w=>widgets[w]);if(overview.showAlerts&&!selected.includes('alerts'))selected.push('alerts');if(overview.showInvestments&&!selected.includes('investments'))selected.push('investments');if(overview.showGoals&&!selected.includes('goals'))selected.push('goals');return `${!state.accounts.length?`<div class="notice">Seu espaço está pronto para ganhar vida. Comece cadastrando uma conta e o saldo inicial. ${button('Adicionar conta','new-account','plus','small')}</div>`:''}<div class="metrics">${metric('Saldo disponível',s.available,'Contas correntes + dinheiro em espécie','accounts',true)}${metric('Patrimônio líquido',s.net,'Contas, reservas e investimentos menos dívidas','lock')}${metric('Entradas do mês',s.income,'Receitas recebidas no período','down')}${metric('Despesas do mês',s.expense,'À vista + parcelas deste mês','up')}</div><div class="grid-main">${selected.map(w=>widgets[w]()).join('')}</div>`}
function compactRecentPanel(){const ts=state.transactions.filter(t=>t.date.slice(0,7)===month).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return `<section class="panel dashboard-panel"><div class="panelhead"><h2>Últimos lançamentos</h2>${button('Ver todos','nav','right','subtle small','transactions')}</div>${ts.length?txTable(ts,false):empty('Nenhum lançamento','Os registros do mês aparecerão aqui.','new-tx','Registrar lançamento')}</section>`}
function compactFixedPanelLegacy(){const rs=state.recurring.filter(recurringPending).sort((a,b)=>(a.schedule==='flexible'?99:a.day)-(b.schedule==='flexible'?99:b.day)).slice(0,3);return `<section class="panel dashboard-panel"><div class="panelhead"><h2>Compromissos do mês</h2>${button('Ver todos','nav','right','subtle small','fixed')}</div><div class="panelbody">${rs.length?rs.map(r=>`<div class="due-row"><div class="account-symbol">${r.schedule==='flexible'?'↻':r.day}</div><div class="row-detail"><strong>${esc(r.name)}</strong><small>${esc(recurringDetail(r))}</small></div><div class="row-money">${money(r.amount)}</div></div>`).join(''):empty('Tudo em dia','Nenhum compromisso pendente neste mês.','new-fixed','Adicionar gasto fixo')}</div></section>`}
function compactAccountsPanel(){const ordered=state.accounts.map(a=>({a,balance:accountBalance(state,a.id,dateAt(month,31))})).filter(x=>x.balance!==0).sort((x,y)=>Number(y.balance)-Number(x.balance)).slice(0,4);return `<section class="panel dashboard-panel"><div class="panelhead"><h2>Onde está seu dinheiro</h2>${button('Ver contas','nav','right','subtle small','accounts')}</div><div class="panelbody">${ordered.length?ordered.map(({a,balance})=>`<div class="account-row"><div class="account-symbol" style="color:${a.color};background:${a.color}15">${esc(a.name.slice(0,2))}</div><div class="row-detail"><strong>${esc(a.name)}</strong><small>${kindName[a.kind]}</small></div><div class="row-money">${money(balance)}</div></div>`).join(''):empty('Cada conta tem seu lugar','Cadastre uma conta para começar.','new-account','Adicionar conta')}</div></section>`}
function miniAlertsPanel(){const items=alertItems();return `<section class="panel mini-panel"><div class="panelhead"><h2>Próximos vencimentos</h2><span class="meta muted">${items.length} pendente${items.length===1?'':'s'}</span></div><div class="panelbody">${items.length?items.slice(0,2).map(x=>`<div class="mini-line"><span><strong>${esc(x.text)}</strong><small>${shortDate(x.date)} · ${dueLabel(x.state)}</small></span><strong>${x.detail}</strong></div>`).join(''):'<p class="hint">Nenhum vencimento pendente.</p>'}</div></section>`}
function miniInvestmentsPanel(){const total=investmentTotal(state,'current',today()),yieldTotal=state.investments.reduce((n,i)=>n+investmentYield(i,today()),0);return `<section class="panel mini-panel"><div class="panelhead"><h2>Investimentos</h2>${button('Ver investimentos','nav','right','subtle small','investments')}</div><div class="panelbody"><div class="mini-values"><span><small>Valor atual</small><strong>${money(total)}</strong></span><span><small>Rendimento</small><strong class="${yieldTotal>=0?'positive':'negative'}">${money(yieldTotal)}</strong></span></div></div></section>`}
function miniGoalsPanel(){const open=state.goals.filter(g=>g.status!=='paid'&&g.status!=='cancelled').slice(0,2);return `<section class="panel mini-panel"><div class="panelhead"><h2>Objetivos</h2>${button('Ver objetivos','nav','right','subtle small','goals')}</div><div class="panelbody">${open.length?open.map(g=>`<div class="mini-line"><span><strong>${esc(g.name)}</strong><small>${money(g.saved)} planejados</small></span><strong>${g.target?Math.round(g.saved/g.target*100):0}%</strong></div>`).join(''):'<p class="hint">Nenhum objetivo em aberto.</p>'}</div></section>`}
function dashboardV3(){const s=summary(state,month),overview=state.settings.overview||{};const minis=[];if(overview.showAlerts!==false)minis.push(miniAlertsPanel());if(overview.showInvestments!==false)minis.push(miniInvestmentsPanel());if(overview.showGoals!==false)minis.push(miniGoalsPanel());return `${!state.accounts.length?`<div class="notice">Seu espaço está pronto para ganhar vida. Comece cadastrando uma conta e o saldo inicial. ${button('Adicionar conta','new-account','plus','small')}</div>`:''}<div class="metrics">${metric('Saldo disponível',s.available,'Contas correntes + dinheiro em espécie','accounts',true)}${metric('Patrimônio líquido',s.net,'Contas, reservas e investimentos menos dívidas','lock')}${metric('Entradas do mês',s.income,'Receitas recebidas no período','down')}${metric('Despesas do mês',s.expense,'À vista + parcelas deste mês','up')}</div><div class="dashboard-info-grid"><div>${compactRecentPanel()}</div><div>${compactAccountsPanel()}${compactFixedPanel()}</div></div><div class="dashboard-chart">${flowPanel()}</div>${minis.length?`<div class="dashboard-mini-grid">${minis.join('')}</div>`:''}`}
function cardFormV2(id){const c=state.cards.find(c=>c.id===id)||{name:'',type:'credit',limit:0,closing:20,due:28,color:'#162c42'};dialog(id?'Editar cartão':'Novo cartão',`${field('name','Nome do cartão',c.name,'text','required maxlength="60" placeholder="Ex.: Nubank"')}${field('last4','Últimos 4 dígitos',c.last4||'','text','inputmode="numeric" pattern="[0-9]{0,4}" maxlength="4" placeholder="Ex.: 1234"')}${select('kind','Uso do cartão',Object.entries(cardTypeName),c.type)}<div class="formgrid">${field('limit','Limite de crédito (R$)',moneyInput(c.limit),'number','min="0" step="0.01"')}${field('color','Cor do cartão',c.color,'color')}${field('closing','Dia do fechamento',c.closing,'number','required min="1" max="31"')}${field('due','Dia do vencimento',c.due,'number','required min="1" max="31"')}</div><p class="hint">Débito registra a saída no momento do lançamento. Crédito organiza compras em faturas e parcelas. A opção combinada aceita os dois usos.</p>`,true,async f=>{const v={id:id||uid(),name:f.get('name').trim(),type:f.get('kind'),limit:cents(f.get('limit')||0),color:f.get('color'),closing:Number(f.get('closing')),due:Number(f.get('due'))};if(!v.name)throw Error('Informe o nome do cartão.');await commit(s=>{if(id)s.cards[s.cards.findIndex(x=>x.id===id)]=v;else s.cards.push(v)},'Cartão salvo')})}
function cardsPageV2(){if(!state.cards.length)return `<section class="panel">${empty('Seus cartões em um só lugar','Crie um cartão e escolha se ele será de débito, crédito ou os dois.','new-card','Adicionar cartão','cards')}</section>`;return `<div class="two">${state.cards.map(c=>{const credit=c.type!=='debit',inv=credit?invoice(state,c.id,month):{total:0,due:0},debt=credit?outstanding(state,c.id):0,totalLimit=credit?cardLimit(state,c):0,limit=Math.max(0,totalLimit-debt),linked=credit&&c.limitSource==='investment'?state.investments.find(i=>i.id===c.limitInvestmentId):null,number=c.last4?`•••• •••• •••• ${c.last4}`:'•••• •••• •••• ••••';return `<section class="panel"><div class="panelbody"><div class="credit-visual" style="background:linear-gradient(135deg,${c.color},#0d2134 88%)"><div class="actions card-brand"><h2>${esc(c.name)}</h2><strong class="card-network">orbe.</strong></div><div class="card-middle"><div class="chip" aria-hidden="true"><i></i><i></i><i></i></div><span class="contactless" aria-hidden="true">◔</span><div class="card-number">${number}</div></div><div class="card-bottom"><span class="card-holder">ORBE PESSOAL</span><span class="card-validity">${credit?`FECHA ${String(c.closing).padStart(2,'0')} · VENCE ${String(c.due).padStart(2,'0')}`:'DÉBITO'}</span></div></div>${credit?`<div class="splitline sectiongap"><span>Fatura · ${monthName(month)}</span><strong>${money(inv.total)}</strong></div><div class="progress"><div style="width:${Math.min(100,totalLimit?debt/totalLimit*100:0)}%"></div></div><div class="splitline meta muted"><span>Comprometido ${money(debt)}</span><span>Limite disponível ${money(limit)}</span></div>${linked?`<p class="hint guarantee-note">Garantido por ${esc(linked.name)} · ${money(investmentValue(linked))} investidos no ${esc(linked.institution)}</p>`:''}`:''}<div class="actions sectiongap">${c.type!=='credit'?button('Registrar débito','new-debit','plus','primary',c.id):''}${credit?button('Nova compra','new-purchase','plus','primary',c.id):''}${credit?button('Ver fatura','invoice','cards','',c.id):''}${button('Editar','edit-card','edit','subtle small',c.id)}${button('','delete-card','trash','subtle small danger',c.id)}</div>${credit?`<div class="sectiongap"><span class="pill ${inv.total&&inv.due===0?'green':''}">${inv.total===0?'Nenhuma parcela neste mês':inv.due===0?'Fatura paga':'Em aberto: '+money(inv.due)}</span></div>`:''}</div></section>`}).join('')}</div><div class="notice sectiongap">Cartões de débito e crédito ficam separados. Só cartões de crédito ou combinados recebem compras parceladas e faturas.</div>`}

function txFormV2(id,defaults={}){if(!state.accounts.length){accountForm();toast('Primeiro, cadastre uma conta.');return}const old=state.transactions.find(t=>t.id===id);const t=old||{type:'expense',description:'',amount:0,date:today(),accountId:state.accounts[0].id,categoryId:'',paymentCardId:defaults.paymentCardId||'',notes:'',extra:{},...defaults};const extras=state.settings.fields.map(f=>field('extra-'+f.id,esc(f.name),t.extra?.[f.id]||'',f.type,f.type==='number'?'step="any"':'maxlength="500"')).join('');const debitOpts=[['','Sem cartão'],...state.cards.filter(c=>c.type==='debit'||c.type==='both').map(c=>[c.id,c.name])];dialog(old?'Editar lançamento':'Novo lançamento',`${t.recurringId?'<div class="notice">Este lançamento confirma um gasto fixo.</div>':''}<div class="formgrid">${select('type','Tipo',[['expense','Despesa'],['income','Receita'],['transfer','Transferência']],t.type)}${field('amount','Valor (R$)',t.amount?moneyInput(t.amount):'','number','required min="0.01" step="0.01"')}<div class="span2">${field('description','Descrição',t.description,'text','required maxlength="180" placeholder="Ex.: mercado"')}</div>${field('date','Data',t.date,'date','required')}${select('accountId','Conta de origem / recebimento',acOpts(),t.accountId,'required')}<div id="tx-destination" class="span2" ${t.type!=='transfer'?'hidden':''}>${select('toAccountId','Conta de destino',[['','Selecione'],...acOpts()],t.toAccountId||'')}</div><div id="tx-category" class="span2" ${t.type==='transfer'?'hidden':''}>${select('categoryId','Categoria',catOpts(t.type==='income'?'income':'expense'),t.categoryId)}</div><div id="tx-card" class="span2" ${t.type!=='expense'?'hidden':''}>${select('paymentCardId','Cartão de débito (opcional)',debitOpts,t.paymentCardId||'')}</div>${extras}<div class="field span2"><label for="f-notes">Observação</label><textarea id="f-notes" name="notes" maxlength="2000">${esc(t.notes)}</textarea></div></div>`,true,async f=>{const type=f.get('type'),accountId=f.get('accountId'),toAccountId=f.get('toAccountId');if(type==='transfer'&&(!toAccountId||toAccountId===accountId))throw Error('Escolha duas contas diferentes.');const cardId=type==='expense'?f.get('paymentCardId'):'';if(cardId&&!state.cards.some(c=>c.id===cardId&&(c.type==='debit'||c.type==='both')))throw Error('Escolha um cartão de débito.');const value={...t,id:old?.id||uid(),type,accountId,toAccountId:type==='transfer'?toAccountId:'',categoryId:type==='transfer'?'':f.get('categoryId'),paymentCardId:cardId,description:f.get('description').trim(),amount:cents(f.get('amount')),date:f.get('date'),notes:f.get('notes'),extra:Object.fromEntries(state.settings.fields.map(x=>[x.id,f.get('extra-'+x.id)]))};if(!value.description)throw Error('Informe uma descrição.');await commit(s=>{if(old)s.transactions[s.transactions.findIndex(x=>x.id===id)]=value;else s.transactions.push(value)},'Lançamento salvo')});document.querySelector('#f-type').onchange=e=>{const type=e.target.value;document.querySelector('#tx-destination').hidden=type!=='transfer';document.querySelector('#tx-category').hidden=type==='transfer';document.querySelector('#tx-card').hidden=type!=='expense';const cat=document.querySelector('#f-categoryId');if(cat)cat.innerHTML=catOpts(type==='income'?'income':'expense').map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('')};}
function categoryFormV2(id){const c=state.categories.find(c=>c.id===id);dialog(c?'Editar categoria':'Nova categoria',`${field('name','Nome',c?.name||'','text','required maxlength="60"')}${select('kind','Usar em',[['expense','Despesas'],['income','Receitas'],['both','Despesas e receitas']],c?.type||'expense')}`,true,async f=>{const name=f.get('name').trim();if(!name)throw Error('Informe um nome.');if(state.categories.some(c=>c.id!==id&&c.name.toLowerCase()===name.toLowerCase()))throw Error('Já existe uma categoria com esse nome.');await commit(s=>{if(id){const x=s.categories.find(c=>c.id===id);x.name=name;x.type=f.get('kind')}else s.categories.push({id:uid(),name,type:f.get('kind')})},'Categoria salva')})}
function projectForm(id){const p=state.projects.find(p=>p.id===id)||{name:'',archived:false};dialog(id?'Editar projeto':'Novo projeto',`${field('name','Nome do projeto',p.name,'text','required maxlength="100"')}${select('archived','Situação',[[false,'Ativo'],[true,'Arquivado']],p.archived)}`,true,async f=>{const name=f.get('name').trim();if(!name)throw Error('Informe um nome.');await commit(s=>{const v={id:id||uid(),name,archived:f.get('archived')==='true'};if(id)s.projects[s.projects.findIndex(x=>x.id===id)]=v;else s.projects.push(v)},'Projeto salvo')})}
function projectsPanel(scope=state.goals){const projects=state.projects.filter(p=>goalProjectFilter==='all'||p.id===goalProjectFilter).map(p=>({...p,count:scope.filter(g=>g.projectId===p.id).length})).filter(p=>goalProjectFilter!=='all'||p.count>0||(!goalSearch&&goalStatusFilter==='active'));return `<section class="panel sectiongap projects-panel"><div class="panelhead"><div><h2>Projetos</h2><p>Grupos para manter seus objetivos no lugar certo.</p></div>${button('Novo projeto','new-project','plus','small')}</div><div class="panelbody">${projects.length?`<div class="project-list">${projects.map(p=>`<div class="project-row"><div class="project-mark">${esc(p.name.slice(0,2).toUpperCase())}</div><div class="row-detail"><strong>${esc(p.name)}</strong><small>${p.archived?'Arquivado':'Ativo'} · ${p.count} objetivo(s) nesta seleção</small></div><div class="actions">${button('Editar','edit-project','edit','subtle small',p.id)}${button('','delete-project','trash','subtle small danger',p.id)}</div></div>`).join('')}</div>`:'<p class="hint">Nenhum projeto corresponde aos filtros atuais.</p>'}</div></section>`}

function goalFormV2(id){const g=state.goals.find(g=>g.id===id)||{name:'',target:0,saved:0,projectId:'',priority:'Média',impact:3,status:'planned',description:'',url:'',purchaseBy:'',focus:false,paidAt:'',paidTransactionId:''};const projects=[['','Sem projeto'],...state.projects.filter(p=>!p.archived).map(p=>[p.id,p.name])];dialog(id?'Editar objetivo':'Novo objetivo',`${field('name','Objetivo',g.name,'text','required maxlength="180"')}${field('target','Custo previsto (R$)',g.target?moneyInput(g.target):'','number','required min="0.01" step="0.01"')}<div class="formgrid"><label class="checkline span2 goal-focus-choice"><input name="focus" type="checkbox" ${g.focus?'checked':''}> Manter este item em foco</label><div id="goal-purchase-field" class="span2" ${g.focus?'':'hidden'}>${field('purchaseBy','Data prevista de aquisição',g.purchaseBy||'','date')}<p class="hint">Escolha o dia em que pretende comprar. O foco cria um prazo padrão de 3 meses, que você pode ajustar com exatidão.</p></div>${select('projectId','Projeto',projects,g.projectId)}${select('priority','Prioridade',['Ideia','Baixa','Média','Alta','Urgente'].map(x=>[x,x]),g.priority)}${select('status','Situação',[['planned','Planejado'],['paid','Pago'],['cancelled','Desistido']],g.status)}${field('url','Link de compra',g.url,'url','maxlength="2000"')}<div class="span2">${field('description','Observações',g.description,'text','maxlength="1000"')}</div></div><p class="hint">Ao tirar o foco, a data prevista é removida. Se o prazo vencer sem pagamento enquanto estiver em foco, ele é renovado por mais 3 meses.</p>`,true,async f=>{const focused=f.get('focus')==='on',v={...g,id:id||uid(),name:f.get('name').trim(),target:cents(f.get('target')),projectId:f.get('projectId'),priority:f.get('priority'),status:f.get('status'),url:f.get('url'),description:f.get('description'),purchaseBy:focused?(f.get('purchaseBy')||(!g.purchaseBy?addMonthsDate(today(),3):g.purchaseBy||'')):'',focus:focused};if(!v.name)throw Error('Informe um objetivo.');if(v.url&&!/^https?:\/\//i.test(v.url))throw Error('Use um link iniciado por https:// ou http://.');await commit(s=>{if(id)s.goals[s.goals.findIndex(x=>x.id===id)]=v;else s.goals.push(v)},'Objetivo salvo')});const focusInput=document.querySelector('input[name=focus]'),purchaseField=document.querySelector('#goal-purchase-field'),purchaseInput=document.querySelector('#f-purchaseBy');const sync=()=>{const focused=Boolean(focusInput?.checked);if(purchaseField)purchaseField.hidden=!focused;if(focused&&purchaseInput&&!purchaseInput.value)purchaseInput.value=addMonthsDate(today(),3)};focusInput?.addEventListener('change',sync);sync()}

function payGoal(id){const g=state.goals.find(g=>g.id===id);if(!g||g.paidAt){toast('Este objetivo já foi pago.');return}const cards=[['','Escolher forma de pagamento'],['cash','Conta / débito'],...state.cards.filter(c=>c.type!=='debit').map(c=>[c.id,`Crédito · ${c.name}`])];dialog('Registrar pagamento',`<div class="notice">${esc(g.name)} · isso criará um gasto de ${money(g.target)} ligado ao objetivo.</div>${field('amount','Valor pago (R$)',moneyInput(g.target),'number','required min="0.01" step="0.01"')}${select('method','Forma de pagamento',cards)}${select('accountId','Conta de pagamento',acOpts(),state.accounts[0]?.id||'')}${field('date','Data do pagamento',today(),'date','required')}${field('count','Parcelas no cartão',1,'number','min="1" max="120" step="1"')}`,true,async f=>{const method=f.get('method'),amount=cents(f.get('amount')),date=f.get('date');if(!method)throw Error('Escolha uma forma de pagamento.');await commit(s=>{const fresh=s.goals.find(x=>x.id===id);if(fresh.paidAt)throw Error('Este objetivo já foi pago.');if(method==='cash'){const tx={id:uid(),type:'expense',description:fresh.name,amount,date,accountId:f.get('accountId'),categoryId:'',paymentCardId:'',notes:'Pagamento do objetivo',extra:{},goalId:id};s.transactions.push(tx);fresh.paidTransactionId=tx.id}else{const c=s.cards.find(x=>x.id===method);if(!c||c.type==='debit')throw Error('Escolha um cartão de crédito ou combinado.');const p={id:uid(),cardId:c.id,description:fresh.name,amount,count:Number(f.get('count'))||1,date,firstMonth:firstInvoice(date,c),categoryId:'',notes:'Pagamento do objetivo',goalId:id};s.purchases.push(p);fresh.paidTransactionId=p.id}fresh.saved=amount;fresh.paidAt=date;fresh.status='paid'},'Pagamento registrado')},'Registrar pagamento')}
function goalMonthsUntil(g){if(!g?.purchaseBy)return 3;const [y,m]=today().slice(0,7).split('-').map(Number),[ty,tm]=String(g.purchaseBy).slice(0,7).split('-').map(Number),n=(ty-y)*12+tm-m;return Number.isFinite(n)?Math.max(1,Math.min(120,n)):3}
