async function removeCustom(kind,id){const list=kind==='investment'?state.investments:state.projects;const item=list.find(x=>x.id===id);if(kind==='project'&&state.goals.some(g=>g.projectId===id)){toast('Este projeto ainda tem objetivos vinculados.');return}if(kind==='investment'&&(state.transactions.some(t=>t.type==='transfer'&&t.toInvestmentId===id)||state.investments.some(x=>x.sourceInvestmentId===id))){toast('Este investimento tem vínculos. Edite os cofres ou transferências antes de excluí-lo.');return}if(!item)return;modal.close();dialog('Confirmar exclusão',`<p>Excluir <strong>${esc(item.name||item.institution)}</strong>?</p>`,true,async()=>commit(s=>{s[kind==='investment'?'investments':'projects']=s[kind==='investment'?'investments':'projects'].filter(x=>x.id!==id)},'Registro excluído'),'Excluir')}
