function csvRows(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);if(!lines.length)return[];const parse=line=>{const out=[];let v='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'&&line[i+1]==='"'){v+='"';i++;continue}if(ch==='"'){q=!q;continue}if((ch===','||ch===';')&&!q){out.push(v.trim());v='';continue}v+=ch}out.push(v.trim());return out};const headers=parse(lines[0]).map(x=>x.toLowerCase());return lines.slice(1).map(line=>{const vals=parse(line),row={};headers.forEach((h,i)=>row[h]=vals[i]||'');return row})}
function rowValue(row,names){const key=Object.keys(row).find(k=>names.some(n=>k===n||k.includes(n)));return key?row[key]:''}
function parseImportAmount(v){let x=String(v||'').replace(/r\$|\s/gi,'');if(x.includes(',')&&x.includes('.'))x=x.replace(/\./g,'').replace(',','.');else if(x.includes(','))x=x.replace(',','.');const n=Number(x);return Number.isFinite(n)?cents(n):0}
function parseImportDate(v){const x=String(v||'').trim();if(/^\d{2}\/\d{2}\/\d{4}$/.test(x))return `${x.slice(6)}-${x.slice(3,5)}-${x.slice(0,2)}`;if(/^\d{4}-\d{2}-\d{2}$/.test(x))return x;return today()}
function notionImport(){if(!state.accounts.length){accountForm();toast('Crie uma conta antes de importar os lançamentos.');return}dialog('Importar dados do Notion',`${field('file','Arquivo CSV ou JSON exportado do Notion','','file','accept=".csv,.json,.txt,application/json,text/csv" required')}<p class="hint">A primeira linha do CSV deve ter colunas como data, descrição, valor, tipo e categoria. O arquivo original não é enviado para lugar nenhum.</p>`,true,async f=>{const file=f.get('file');if(!file||!file.size)throw Error('Escolha um arquivo.');const text=await file.text();let rows=[];if(file.name.toLowerCase().endsWith('.json')){const data=JSON.parse(text);rows=Array.isArray(data)?data:(Array.isArray(data.results)?data.results:[])}else rows=csvRows(text);if(!rows.length)throw Error('Não encontrei linhas para importar.');await commit(s=>{let count=0;for(const row of rows){const get=(names)=>{if(typeof row!=='object')return'';const raw=rowValue(Object.fromEntries(Object.entries(row).map(([k,v])=>[k.toLowerCase(),String(v??'')])),names);return String(raw??'').trim()};const description=get(['descrição','descricao','description','nome','name','título','titulo','title'])||'Importado do Notion';const amount=parseImportAmount(get(['valor','amount','preço','preco']));if(!amount)continue;const rawType=get(['tipo','type','natureza']).toLowerCase();const type=/receita|entrada|income|salary|salário/.test(rawType)?'income':'expense';const date=parseImportDate(get(['data','date','dia']));const catName=get(['categoria','category','grupo']);let categoryId='';if(catName){let cat=s.categories.find(c=>c.name.toLowerCase()===catName.toLowerCase()&&((c.type==='both')||c.type===type));if(!cat){cat={id:uid(),name:catName,type};s.categories.push(cat)}categoryId=cat.id}s.transactions.push({id:uid(),type,description,amount,date,accountId:s.accounts[0].id,categoryId,paymentCardId:'',notes:'Importado do Notion',extra:{}});count++}if(!count)throw Error('Nenhuma linha com valor válido foi encontrada.')},'Dados do Notion importados')})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="import-notion"]');if(b){e.stopImmediatePropagation();notionImport()}},true);
async function fullImport(){
  if(session?.demo){toast('Entre no seu cofre para importar a migração.');return}
  dialog('Aplicar migração do Notion','<p>Vou carregar a exportação completa preparada a partir das suas páginas financeiras. Os CSVs originais, fórmulas e registros que não puderam virar lançamentos ficam preservados dentro do cofre.</p><label class="checkline"><input name="confirm" type="checkbox" required> Entendi e quero importar todos os dados para este usuário.</label>',true,async()=>{
    if(state.accounts.length||state.transactions.length||state.goals.length)throw Error('Este cofre já tem dados. Exporte um backup antes de substituir o conteúdo.');
    const response=await fetch(`./notion-migration.json?v=${Date.now()}`);
    if(!response.ok)throw Error('A migração preparada não está disponível neste endereço local.');
    const data=validate(migrate(await response.json()));
    await commit(s=>{for(const key of Object.keys(s))delete s[key];Object.assign(s,data)},'Dados do Notion importados e preservados');
  },'Importar tudo');
}
