function compactFixedPanel(){const fixedRows=state.recurring.filter(recurringPending).sort((a,b)=>(a.schedule==='flexible'?99:a.day)-(b.schedule==='flexible'?99:b.day)).map(r=>({kind:'fixed',sort:r.schedule==='flexible'?'9999-12-31':dateAt(month,r.day),label:r.name,detail:recurringDetail(r),amount:r.amount,icon:r.schedule==='flexible'?'↻':String(r.day)}));const focusRows=state.goals.filter(g=>g.focus&&g.status!=='paid'&&g.status!=='cancelled'&&(g.target||0)>(g.saved||0)).map(g=>{const remaining=Math.max(0,(g.target||0)-(g.saved||0)),monthly=goalMonthly(g);return {kind:'focus',sort:g.purchaseBy||'9999-12-31',label:g.name,detail:monthly?`Guardar ${money(monthly)}/mês${g.purchaseBy?' · até '+shortDate(g.purchaseBy):''}`:`Em foco · faltam ${money(remaining)}`,amount:monthly||remaining,icon:'★'}}).sort((a,b)=>a.sort.localeCompare(b.sort));const rows=[...focusRows,...fixedRows].slice(0,4);return `<section class="panel dashboard-panel"><div class="panelhead"><h2>Compromissos do mês</h2>${button('Ver todos','nav','right','subtle small','fixed')}</div><div class="panelbody">${rows.length?rows.map(x=>`<div class="due-row ${x.kind==='focus'?'focus-commitment':''}"><div class="account-symbol">${x.icon}</div><div class="row-detail"><strong>${esc(x.label)}</strong><small>${esc(x.detail)}</small></div><div class="row-money">${money(x.amount)}${x.kind==='focus'?'<small>em foco</small>':''}</div></div>`).join(''):empty('Tudo em dia','Nenhum compromisso pendente neste mês.','new-fixed','Adicionar gasto fixo')}</div></section>`}
